-- ------------------------------------------------------------
-- 07/10/2026 — DONNÉES du Tour 3 : épreuve de prospection (« Business Game T3 »)
-- ------------------------------------------------------------
-- Brief de Felix du 06/10/2026, §5 et §6, avec ses décisions du 07/10 :
--   * grille de 74 critères, total 81 points (bonus inclus,
--     « Échange individuel » gardé) ; répartition : Le mail 21, L'appel téléphonique 20, L'échange individuel 20, L'échange groupé 20 ;
--   * critère « Réponse à la problématique » en position 73 (base 0),
--     barème 8 ; banque de 7 questions
--     (question « BV » retirée) ;
--   * pas d'évaluation du groupe (group_grid = {"disabled": true}) ;
--   * consignes (description) adaptées au déroulé de 50 minutes.
--
-- À APPLIQUER APRÈS supabase-migration-tour3-notation.sql, et SEULEMENT si le
-- Tour 3 n'a encore aucune note : le bloc s'arrête sinon (les notes sont
-- indexées par la position des critères, changer la grille les fausserait).

DO $$
DECLARE
  nb_notes integer;
  ep record;
BEGIN
  SELECT tour, is_group_epreuve INTO ep FROM epreuves WHERE id = '368ab3c5-95c7-4da5-bc47-f0decf4e4063';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Épreuve Business Game T3 introuvable.';
  END IF;
  -- Épreuve DE GROUPE obligatoire : sinon un créneau à 3 jurys passerait en
  -- « binôme » (une seule note partagée) et chaque jury ne noterait plus SON
  -- candidat.
  IF ep.tour <> 3 OR ep.is_group_epreuve IS NOT TRUE THEN
    RAISE EXCEPTION 'Épreuve inattendue (tour %, de groupe : %) : grille NON modifiée.', ep.tour, ep.is_group_epreuve;
  END IF;

  SELECT count(*) INTO nb_notes
  FROM candidate_evaluations
  WHERE epreuve_id = '368ab3c5-95c7-4da5-bc47-f0decf4e4063';
  IF nb_notes > 0 THEN
    RAISE EXCEPTION 'Le Business Game T3 a déjà % note(s) : grille NON modifiée.', nb_notes;
  END IF;

  UPDATE epreuves
  SET evaluation_questions = '[{"section": "Le mail", "q": "Mail — Objet du mail présent et explicite", "weight": 1, "input": "checkbox", "hint": "Clarté et concision"}, {"section": "Le mail", "q": "Mail — Structure logique : présentation, proposition, demande de rendez-vous", "weight": 1, "input": "checkbox", "hint": "Clarté et concision"}, {"section": "Le mail", "q": "Mail — Court : paragraphes de 3 à 4 lignes, lisible en moins d''une minute", "weight": 1, "input": "checkbox", "hint": "Clarté et concision"}, {"section": "Le mail", "q": "Mail — Cite le nom de l''entreprise du prospect", "weight": 1, "input": "checkbox", "hint": "Pertinence des informations"}, {"section": "Le mail", "q": "Mail — Mentionne un élément propre au prospect (secteur, actualité, poste, projet repéré sur le site ou LinkedIn)", "weight": 1, "input": "checkbox", "hint": "Pertinence des informations"}, {"section": "Le mail", "q": "Mail — Évoque au moins une prestation adaptée au besoin du prospect", "weight": 1, "input": "checkbox", "hint": "Pertinence des informations"}, {"section": "Le mail", "q": "Mail — Aucune information inutile ou hors sujet", "weight": 1, "input": "checkbox", "hint": "Pertinence des informations"}, {"section": "Le mail", "q": "Mail — Se présente : prénom, nom et rôle dans la JE", "weight": 1, "input": "checkbox", "hint": "Se présente et présente la JE"}, {"section": "Le mail", "q": "Mail — Présente la JE : nom et rattachement à Audencia", "weight": 1, "input": "checkbox", "hint": "Se présente et présente la JE"}, {"section": "Le mail", "q": "Mail — Donne au moins une spécificité de l''association (Junior-Entreprise, but non lucratif, réseau CNJE, étudiants d''école de commerce, tarifs)", "weight": 1, "input": "checkbox", "hint": "Se présente et présente la JE"}, {"section": "Le mail", "q": "Mail — Demande explicite : rendez-vous, appel ou réponse", "weight": 1, "input": "checkbox", "hint": "Appel à l''action"}, {"section": "Le mail", "q": "Mail — Proposition concrète : créneau, durée ou format", "weight": 1, "input": "checkbox", "hint": "Appel à l''action"}, {"section": "Le mail", "q": "Mail — Aucune faute d''orthographe", "weight": 1, "input": "checkbox", "hint": "Qualité de la langue"}, {"section": "Le mail", "q": "Mail — Phrases correctes et fluides, sans faute de syntaxe", "weight": 1, "input": "checkbox", "hint": "Qualité de la langue"}, {"section": "Le mail", "q": "Mail — Registre professionnel : vouvoiement, aucune familiarité ni abréviation", "weight": 1, "input": "checkbox", "hint": "Qualité de la langue"}, {"section": "Le mail", "q": "Mail — Formule d''appel personnalisée avec le nom du prospect", "weight": 1, "input": "checkbox", "hint": "Formules de politesse et signature"}, {"section": "Le mail", "q": "Mail — Formule de clôture", "weight": 1, "input": "checkbox", "hint": "Formules de politesse et signature"}, {"section": "Le mail", "q": "Mail — Signature : prénom, nom, fonction et nom de la JE", "weight": 1, "input": "checkbox", "hint": "Formules de politesse et signature"}, {"section": "Le mail", "q": "Mail — Numéro de téléphone dans la signature", "weight": 1, "input": "checkbox", "hint": "Formules de politesse et signature"}, {"section": "Le mail", "q": "Mail — Adresse mail professionnelle (adresse de la JE ou format prénom.nom)", "weight": 1, "input": "checkbox", "hint": "Formules de politesse et signature"}, {"section": "Le mail", "q": "Mail — BONUS : phrase d''accroche originale", "weight": 1, "input": "checkbox", "hint": "Un seul point maximum"}, {"section": "L''appel téléphonique", "q": "Appel — Salue et se présente (prénom, nom) dès les premières secondes", "weight": 1, "input": "checkbox", "hint": "Introduction claire et accrocheuse"}, {"section": "L''appel téléphonique", "q": "Appel — Présente la JE et Audencia en une phrase", "weight": 1, "input": "checkbox", "hint": "Introduction claire et accrocheuse"}, {"section": "L''appel téléphonique", "q": "Appel — Vérifie qu''il parle à la bonne personne et que le moment convient", "weight": 1, "input": "checkbox", "hint": "Introduction claire et accrocheuse"}, {"section": "L''appel téléphonique", "q": "Appel — Annonce tout de suite la raison de l''appel, liée au prospect", "weight": 1, "input": "checkbox", "hint": "Introduction claire et accrocheuse"}, {"section": "L''appel téléphonique", "q": "Appel — Débit posé, voix audible", "weight": 1, "input": "checkbox", "hint": "Éloquence"}, {"section": "L''appel téléphonique", "q": "Appel — Pas de tics de langage répétés (« euh », « du coup », « en fait »)", "weight": 1, "input": "checkbox", "hint": "Éloquence"}, {"section": "L''appel téléphonique", "q": "Appel — Ton dynamique, sourire dans la voix", "weight": 1, "input": "checkbox", "hint": "Éloquence"}, {"section": "L''appel téléphonique", "q": "Appel — Parle naturellement, sans lire un texte mot à mot", "weight": 1, "input": "checkbox", "hint": "Éloquence"}, {"section": "L''appel téléphonique", "q": "Appel — Pose au moins une question ouverte sur les besoins du prospect", "weight": 1, "input": "checkbox", "hint": "Capacité à retenir l''attention"}, {"section": "L''appel téléphonique", "q": "Appel — Rebondit sur ce que dit le prospect au lieu de dérouler son discours", "weight": 1, "input": "checkbox", "hint": "Capacité à retenir l''attention"}, {"section": "L''appel téléphonique", "q": "Appel — Laisse parler le prospect, ne monopolise pas la parole", "weight": 1, "input": "checkbox", "hint": "Capacité à retenir l''attention"}, {"section": "L''appel téléphonique", "q": "Appel — Relance l''intérêt par un exemple concret ou une mission similaire", "weight": 1, "input": "checkbox", "hint": "Capacité à retenir l''attention"}, {"section": "L''appel téléphonique", "q": "Appel — Cite un élément concret sur l''entreprise du prospect", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''appel téléphonique", "q": "Appel — Propose une prestation cohérente avec le besoin exprimé", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''appel téléphonique", "q": "Appel — Avance au moins deux atouts de la JE (coût, réactivité, regard étudiant, suivi qualité)", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''appel téléphonique", "q": "Appel — Répond à l''objection par un argument, sans se décourager", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''appel téléphonique", "q": "Appel — Adapte son discours au profil joué (pressé, sceptique ou déjà accompagné)", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''appel téléphonique", "q": "Appel — Obtient ou propose une prochaine étape datée", "weight": 1, "input": "checkbox", "hint": "Conclusion de l''appel"}, {"section": "L''appel téléphonique", "q": "Appel — Récapitule ce qui a été convenu", "weight": 1, "input": "checkbox", "hint": "Conclusion de l''appel"}, {"section": "L''appel téléphonique", "q": "Appel — Remercie et prend congé poliment", "weight": 1, "input": "checkbox", "hint": "Conclusion de l''appel"}, {"section": "L''échange individuel", "q": "Individuel — Tenue soignée, adaptée à un rendez-vous client", "weight": 1, "input": "checkbox", "hint": "Tenue et attitude"}, {"section": "L''échange individuel", "q": "Individuel — Posture ouverte, regard soutenu", "weight": 1, "input": "checkbox", "hint": "Tenue et attitude"}, {"section": "L''échange individuel", "q": "Individuel — Salue, sourit et remercie le jury", "weight": 1, "input": "checkbox", "hint": "Souriant et courtois"}, {"section": "L''échange individuel", "q": "Individuel — Reste poli et professionnel, même sur une question déstabilisante", "weight": 1, "input": "checkbox", "hint": "Souriant et courtois"}, {"section": "L''échange individuel", "q": "Individuel — Débit de parole posé", "weight": 1, "input": "checkbox", "hint": "À l''aise"}, {"section": "L''échange individuel", "q": "Individuel — Pas de gestes parasites (stylo, mains, jambes)", "weight": 1, "input": "checkbox", "hint": "À l''aise"}, {"section": "L''échange individuel", "q": "Individuel — Gère un blanc ou une question imprévue sans se déstabiliser", "weight": 1, "input": "checkbox", "hint": "À l''aise"}, {"section": "L''échange individuel", "q": "Individuel — Prestation liée à l''activité réelle du prospect", "weight": 1, "input": "checkbox", "hint": "Pertinence des choix de prestation — « Pourquoi présentez-vous cette prestation à ce client ? »"}, {"section": "L''échange individuel", "q": "Individuel — Justifie le choix par des critères (secteur, taille, enjeu du prospect)", "weight": 1, "input": "checkbox", "hint": "Pertinence des choix de prestation — « Quels critères as-tu pris en compte ? »"}, {"section": "L''échange individuel", "q": "Individuel — Nomme précisément la prestation", "weight": 1, "input": "checkbox", "hint": "Connaissance des prestations"}, {"section": "L''échange individuel", "q": "Individuel — Décrit au moins trois phases de la prestation", "weight": 1, "input": "checkbox", "hint": "Connaissance des prestations — « Quelles phases peut-on inclure ? »"}, {"section": "L''échange individuel", "q": "Individuel — Cite au moins un livrable concret remis au client", "weight": 1, "input": "checkbox", "hint": "Connaissance des prestations"}, {"section": "L''échange individuel", "q": "Individuel — Identifie un enjeu ou un besoin du prospect", "weight": 1, "input": "checkbox", "hint": "Compréhension de la situation du prospect"}, {"section": "L''échange individuel", "q": "Individuel — S''appuie sur des informations tirées du site web ou du LinkedIn", "weight": 1, "input": "checkbox", "hint": "Compréhension de la situation du prospect"}, {"section": "L''échange individuel", "q": "Individuel — Sait dire ce qui, dans son mail, doit capter ce prospect en particulier", "weight": 1, "input": "checkbox", "hint": "Compréhension de la situation du prospect"}, {"section": "L''échange individuel", "q": "Individuel — Réponses structurées : idée principale, puis justification", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''échange individuel", "q": "Individuel — Client sans créneau : propose un appel court, une date plus lointaine ou un échange par mail", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''échange individuel", "q": "Individuel — Client muet : relance planifiée (environ une semaine), puis changement de canal", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''échange individuel", "q": "Individuel — Client hésitant : rassure par des références, un devis gratuit ou un découpage en phases", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''échange individuel", "q": "Individuel — Connaît d''autres canaux que le mail : téléphone, LinkedIn, réseau Alumni, salons", "weight": 1, "input": "checkbox", "hint": "Qualité de l''argumentation"}, {"section": "L''échange groupé", "q": "Groupé — Laisse finir les autres, ne coupe pas la parole", "weight": 1, "input": "checkbox", "hint": "À l''écoute de ses camarades"}, {"section": "L''échange groupé", "q": "Groupé — Reprend ou cite l''idée d''un camarade pour la prolonger", "weight": 1, "input": "checkbox", "hint": "À l''écoute de ses camarades"}, {"section": "L''échange groupé", "q": "Groupé — Prend la parole dès les premières minutes", "weight": 1, "input": "checkbox", "hint": "Affirme ses idées"}, {"section": "L''échange groupé", "q": "Groupé — Maintient une idée avec un argument quand elle est contestée", "weight": 1, "input": "checkbox", "hint": "Affirme ses idées"}, {"section": "L''échange groupé", "q": "Groupé — Émet au moins deux propositions concrètes", "weight": 1, "input": "checkbox", "hint": "Pro-actif : émet des propositions"}, {"section": "L''échange groupé", "q": "Groupé — Organise le débat : propose une méthode, surveille le temps", "weight": 1, "input": "checkbox", "hint": "Pro-actif : émet des propositions"}, {"section": "L''échange groupé", "q": "Groupé — Fait une synthèse ou pousse vers une conclusion commune", "weight": 1, "input": "checkbox", "hint": "Pro-actif : émet des propositions"}, {"section": "L''échange groupé", "q": "Groupé — Cherche la cause du problème avant de proposer des solutions", "weight": 1, "input": "checkbox", "hint": "Qualité de la réflexion"}, {"section": "L''échange groupé", "q": "Groupé — Priorise : distingue l''urgent du long terme", "weight": 1, "input": "checkbox", "hint": "Qualité de la réflexion"}, {"section": "L''échange groupé", "q": "Groupé — Envisage les limites ou les risques de sa solution", "weight": 1, "input": "checkbox", "hint": "Qualité de la réflexion"}, {"section": "L''échange groupé", "q": "Groupé — Pense aux acteurs concernés : bureau, chefs de projet, clients, partenaires, école", "weight": 1, "input": "checkbox", "hint": "Qualité de la réflexion"}, {"section": "L''échange groupé", "q": "Groupé — Propose des actions concrètes (qui, quoi, quand) plutôt que des intentions", "weight": 1, "input": "checkbox", "hint": "Qualité de la réflexion"}, {"section": "L''échange groupé", "q": "Réponse à la problématique (pistes de la question choisie)", "weight": 8, "input": "problem_bank", "hint": "1 point par piste citée ou défendue, 8 maximum. Une piste pertinente non listée compte aussi."}]',
      problem_bank = '{"criterionIndex": 73, "maxPoints": 8, "questions": [{"key": "chefs-de-projet", "title": "Chefs de projet pas à la hauteur", "pole": "Qualité, Suivi d''études", "prompt": "Vos chefs de projets ne sont pas à la hauteur, les documents sont en retard, certains livrables ne sont pas de qualité et les problèmes déontologiques s''accumulent, que faites-vous ?", "pistes": ["Fait un état des lieux avant d''agir : quelles études, quels documents, quels chefs de projet", "Échange individuellement avec les chefs de projet pour comprendre les causes (charge de cours, manque de formation, démotivation)", "Traite d''abord les études où le client est impacté, et le prévient si besoin", "Renforce le contrôle qualité : relecture systématique des livrables et validation avant envoi au client", "Forme les chefs de projet aux documents d''étude, au cadre légal et à la déontologie", "Met en place un suivi régulier : point hebdomadaire, tableau des échéances documentaires", "Organise un binômage ou parrainage avec un chef de projet expérimenté", "Rappelle le code de déontologie et prévoit des conséquences graduées en cas de récidive", "Réattribue une étude si un chef de projet ne peut plus la suivre", "Mesure le risque pour la JE : audit CNJE, label, image auprès des clients"]}, {"key": "prospection-abandonnee", "title": "Prospection abandonnée", "pole": "Développement commercial", "prompt": "Vous avez mis en place plusieurs stratégies de prospection dans le but d''encourager les chefs de projet à intégrer cette pratique dans leur quotidien au sein de la Junior Entreprise. Malgré des débuts prometteurs, le mandat finit toujours par abandonner ces initiatives après un certain temps, et la prospection retombe au second plan. Que faites-vous ?", "pistes": ["Cherche pourquoi les initiatives s''essoufflent : manque de temps, de résultats visibles, de suivi", "Fixe des objectifs simples et mesurables (nombre de contacts par semaine et par personne)", "Crée une routine : créneau de prospection commun chaque semaine", "Rend le suivi visible : CRM, tableau de bord, point en réunion de bureau", "Valorise les résultats : rendez-vous obtenus mis en avant, challenge interne", "Facilite le travail : formation, modèles de mails et de scripts, fichiers de cibles déjà qualifiés", "Désigne un référent prospection qui anime et relance", "Diversifie les canaux : Alumni, partenaires, salons, LinkedIn", "Inscrit la démarche dans la passation pour qu''elle survive au mandat", "Mesure l''impact sur le chiffre d''affaires pour montrer l''intérêt de la prospection"]}, {"key": "rq-mexique", "title": "Responsable Qualité au Mexique", "pole": "Présidence, RH", "prompt": "Vous apprenez en février, au bout de 2 mois de mandat, que l''administration d''Audencia décide de changer et réformer certains cursus du PGE. Votre Responsable Qualité est donc obligé de partir au Mexique à partir de septembre pendant 1 semestre. Comment réagissez-vous ?", "pistes": ["Anticipe : sept mois pour s''organiser, sans attendre septembre", "Échange avec le Responsable Qualité sur ses souhaits : continuer à distance ou passer la main", "Distingue les tâches faisables à distance (relecture de documents) de celles qui exigent une présence (audit, réunions)", "Désigne et forme un suppléant avant le départ", "Organise la transmission : documentation des process, accès aux outils", "Répartit temporairement les missions au sein du bureau", "Vérifie le calendrier : audit CNJE, périodes de forte activité pendant l''absence", "Consulte les statuts ou le règlement intérieur pour la procédure de remplacement", "Envisage un recrutement exceptionnel si besoin", "Tient compte du décalage horaire pour organiser des points à distance"]}, {"key": "intervenants", "title": "Recrutement des intervenants", "pole": "Suivi d''études, RH", "prompt": "Une étude est en cours et vous devez recruter des intervenants pour réaliser certaines phases. Beaucoup de personnes de votre mandat sont motivées à y participer. En parallèle, vous avez reçu plusieurs candidatures de la part d''étudiants d''Audencia hors JE. Comment gérez-vous le recrutement des intervenants ?", "pistes": ["Définit les compétences requises pour chaque phase", "Applique un processus transparent avec les mêmes critères pour tous", "Choisit sur la compétence, pas sur l''appartenance au mandat", "Vérifie le cadre légal : statut étudiant, adhésion à la JE, récapitulatif de mission", "Évite les conflits d''intérêts : le chef de projet ou le bureau ne s''attribue pas la mission", "Départage par entretien ou mini-test", "Répond à tous les candidats, refus compris, avec un retour", "Voit les étudiants hors JE comme un vivier de compétences et de futurs membres", "Garde une base de candidats pour les études futures", "Répartit les phases entre plusieurs profils si la qualité le permet"]}, {"key": "membre-fantome", "title": "Membre fantôme", "pole": "RH", "prompt": "Un membre de votre mandat semble se désintéresser de l''association : il ne vient plus aux réunions et répond de moins en moins aux messages. Comment le remotivez-vous ?", "pistes": ["Prend contact en privé, sans reproche, pour comprendre la cause (cours, motivation, conflit, situation personnelle)", "Distingue une baisse passagère d''un désintérêt durable", "Écoute ses attentes : missions, pôle, responsabilités", "Propose une mission plus motivante ou un changement de pôle", "Fixe des attentes claires et une date pour refaire le point", "Associe son responsable de pôle et le pôle RH", "Prévoit un relais pour ses missions en cours (binôme, répartition)", "Rappelle les engagements pris (charte, règlement intérieur)", "Envisage un départ à l''amiable si la situation dure", "Agit sur la cohésion pour prévenir d''autres cas : moments d''équipe, reconnaissance du travail"]}, {"key": "afflux-candidatures", "title": "Afflux de candidatures", "pole": "RH, Présidence", "prompt": "Après vos campagnes de recrutement, vous recevez trois fois plus de candidatures que de places disponibles. Comment organisez-vous la sélection ?", "pistes": ["Définit d''abord les besoins : nombre de places et profils recherchés par pôle", "Fixe des critères communs et une grille d''évaluation", "Ajoute un premier filtre rapide : CV, lettre ou questionnaire", "Organise la sélection en plusieurs tours", "Mobilise et briefe assez de jurys, avec un planning", "Garantit l''équité : mêmes épreuves, mêmes critères, notes harmonisées entre jurys", "Répond à tous les candidats, refus compris", "Garde un vivier des bons profils non retenus (intervenants, prochains recrutements)", "Anticipe la charge de travail du mandat pendant la période", "Pense à l''intégration : ne pas recruter plus que ce que la JE peut former et occuper"]}, {"key": "ca-chiffre-affaires", "title": "Chiffre d''affaires en retard au CA", "pole": "Présidence, Développement commercial", "prompt": "À mi-mandat, le conseil d''administration constate que le chiffre d''affaires est 30 % en dessous de l''objectif. Que proposez-vous ?", "pistes": ["Analyse l''écart : nombre d''études, montant moyen, taux de signature des devis", "Identifie les causes : prospection insuffisante, offre peu adaptée, devis perdus", "Relance les anciens clients et les prospects en attente", "Intensifie la prospection avec des objectifs chiffrés par personne", "Ouvre de nouveaux canaux : Alumni, partenaires, salons, appels d''offres du réseau CNJE", "Revoit l''offre ou les tarifs s''ils ne sont pas compétitifs", "Fixe un plan d''action daté, suivi en bureau ou au prochain CA", "Ajuste les dépenses de la JE en attendant", "Revoit l''objectif s''il était irréaliste, en le justifiant", "Mobilise tout le mandat sans culpabiliser personne"]}]}'::jsonb,
      group_grid = '{"disabled": true}'::jsonb,
      description = 'Épreuve de prospection, en groupe de 3, 50 minutes. Chaque candidat reçoit un prospect réel. Vous rédigez sur papier un mail de premier contact (15 min), puis vous appelez votre prospect, joué par un membre du jury (10 min), suivi d''un retour (5 min). L''épreuve se termine par un débat à trois sur une situation de la vie de la Junior-Entreprise (15 min) et 5 minutes de questions. Ordinateur et téléphone interdits pendant toute l''épreuve.'
  WHERE id = '368ab3c5-95c7-4da5-bc47-f0decf4e4063';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Épreuve Business Game T3 introuvable.';
  END IF;
END $$;
